window.__OPENSTAX_PHYSICS__[9] = {"schemaVersion":"4.0.0-physics","generatedAt":"2026-11-27T01:33:30.713Z","number":9,"code":"ch09","slug":"work-energy-and-simple-machines","title":"Work, Energy, and Simple Machines","titleVi":"Công, Năng Lượng & Máy Cơ Đơn Giản (Work, Energy & Simple Machines)","sections":[{"uid":"hsphys.ch09.sec00","moduleId":"m54268","number":"9.0","slug":"introduction","title":"Introduction","isIntroduction":true,"learningObjectives":[],"bilingualGuide":null,"keyEquations":[],"subsections":[{"uid":"hsphys.ch09.sec00.sub01","title":"Chapter Introduction","summaryVi":null,"paragraphs":["Roller coasters have provided thrills for daring riders around the world since the nineteenth century. Inventors of roller coasters used simple physics to build the earliest examples using railroad tracks on mountainsides and old mines. Modern roller coaster designers use the same basic laws of physics to create the latest amusement park favorites. Physics principles are used to engineer the machines that do the work to lift a roller coaster car up its first big incline before it is set loose to roll. Engineers also have to understand the changes in the car’s energy that keep it speeding over hills, through twists, turns, and even loops.","What exactly is energy? How can changes in force, energy, and simple machines move objects like roller coaster cars? How can machines help us do work? In this chapter, you will discover the answer to this question and many more, as you learn about work, energy, and simple machines."],"figures":[{"sourceId":"fs-id1167066867489","filename":"CNX_HSPhysics_09_00_coaster.jpg","relativePath":"media/CNX_HSPhysics_09_00_coaster.jpg","alt":"A photograph shows a roller coaster cart in an upside down position inside a roller coaster loop of a track"}],"tables":[]}],"workedExamples":[],"snapLabs":[],"tipsAndFeatures":[],"summaryPoints":[],"glossary":[],"assessments":[],"stats":{"learningObjectiveCount":0,"keyEquationCount":0,"subsectionCount":1,"workedExampleCount":0,"snapLabCount":0,"glossaryCount":0,"assessmentCount":0}},{"uid":"hsphys.ch09.sec01","moduleId":"m54271","number":"9.1","slug":"work-power-and-the-work-energy-theorem","title":"Work, Power, and the Work–Energy Theorem","isIntroduction":false,"learningObjectives":["Describe and apply the work–energy theorem","Describe and calculate work and power"],"bilingualGuide":{"notebookSummaryVi":"Công cơ học (W = Fd cosθ), Công suất (P = W/t), Động năng (KE = ½mv²), Thế năng (PE = mgh) và Định lý Công – Động năng (W_net = ΔKE).","wordProblemCues":[{"phraseEn":"work-energy theorem","meaningVi":"Công hợp lực = Độ biến thiên động năng","mathNotation":"W_net = ΔKE"}],"commonTrapsVi":["Cầm cặp đứng yên hoặc đi ngang trên đường bằng: trọng lực vuông góc chiều chuyển động nên Công của trọng lực = 0!"]},"keyEquations":[{"name":"equation for work","formula":"\\(W = \\mathbf{f}d\\)"},{"name":"force","formula":"\\(\\mathbf{f} = w = m\\mathbf{g}\\)"},{"name":"work equivalencies","formula":"\\(W = P{E}_{e} = \\mathbf{f}m\\mathbf{g}\\)"},{"name":"kinetic energy","formula":"\\(KE = \\frac{1}{2}m{\\mathbf{v}}^{2}\\)"},{"name":"work–energy theorem","formula":"\\(W = \\Delta \\text{KE =}\\frac{1}{2}m{\\mathbf{v}}_{2}^{2} - \\frac{1}{2}m{\\mathbf{v}}_{1}^{2}\\)"},{"name":"power","formula":"\\(P = \\frac{W}{t}\\)"}],"subsections":[{"uid":"hsphys.ch09.sec01.sub01","title":"The Work–Energy Theorem","summaryVi":null,"paragraphs":["In physics, the term work has a very specific definition. Work is application of force, \\(\\mathbf{f}\\), to move an object over a distance, d , in the direction that the force is applied. Work, W , is described by the equation","Some things that we typically consider to be work are not work in the scientific sense of the term. Let’s consider a few examples. Think about why each of the following statements is true.","The first two examples are fairly simple. Homework is not work because objects are not being moved over a distance. Lifting a rock up off the ground is work because the rock is moving in the direction that force is applied. The last example is less obvious. Recall from the laws of motion that force is not required to move an object at constant velocity. Therefore, while some force may be applied to keep the rock up off the ground, no net force is applied to keep the rock moving forward at constant velocity.","Work and energy are closely related. When you do work to move an object, you change the object’s energy. You (or an object) also expend energy to do work. In fact, energy can be defined as the ability to do work. Energy can take a variety of different forms, and one form of energy can transform to another. In this chapter we will be concerned with mechanical energy , which comes in two forms: kinetic energy and potential energy .","Let’s examine how doing work on an object changes the object’s energy. If we apply force to lift a rock off the ground, we increase the rock’s potential energy, PE . If we drop the rock, the force of gravity increases the rock’s kinetic energy as the rock moves downward until it hits the ground.","The force we exert to lift the rock is equal to its weight, w , which is equal to its mass, m , multiplied by acceleration due to gravity, g .","The work we do on the rock equals the force we exert multiplied by the distance, d , that we lift the rock. The work we do on the rock also equals the rock’s gain in gravitational potential energy, PE e .","Kinetic energy depends on the mass of an object and its velocity, v .","When we drop the rock the force of gravity causes the rock to fall, giving the rock kinetic energy. When work done on an object increases only its kinetic energy, then the net work equals the change in the value of the quantity \\(\\frac{1}{2}m{\\mathbf{v}}^{2}\\) . This is a statement of the work–energy theorem , which is expressed mathematically as","The subscripts 2 and 1 indicate the final and initial velocity, respectively. This theorem was proposed and successfully tested by James Joule, shown in [Figure 9.1].","Does the name Joule sound familiar? The joule (J) is the metric unit of measurement for both work and energy. The measurement of work and energy with the same unit reinforces the idea that work and energy are related and can be converted into one another. 1.0 J = 1.0 N∙m, the units of force multiplied by distance. 1.0 N = 1.0 kg∙m/s 2 , so 1.0 J = 1.0 kg∙m 2 /s 2 . Analyzing the units of the term (1/2) m v 2 will produce the same units for joules."],"figures":[{"sourceId":"fs-id1167065825613","filename":"CNX_HSPhysics_09_01_Joule.jpg","relativePath":"media/CNX_HSPhysics_09_01_Joule.jpg","alt":"A black and white photograph of James Joule is shown."}],"tables":[]},{"uid":"hsphys.ch09.sec01.sub02","title":"Calculations Involving Work and Power","summaryVi":null,"paragraphs":["In applications that involve work, we are often interested in how fast the work is done. For example, in roller coaster design, the amount of time it takes to lift a roller coaster car to the top of the first hill is an important consideration. Taking a half hour on the ascent will surely irritate riders and decrease ticket sales. Let’s take a look at how to calculate the time it takes to do work.","Recall that a rate can be used to describe a quantity, such as work, over a period of time. Power is the rate at which work is done. In this case, rate means per unit of time . Power is calculated by dividing the work done by the time it took to do the work.","Let’s consider an example that can help illustrate the differences among work, force, and power. Suppose the woman in [Figure 9.1] lifting the TV with a pulley gets the TV to the fourth floor in two minutes, and the man carrying the TV up the stairs takes five minutes to arrive at the same place. They have done the same amount of work \\((\\mathbf{f}d)\\) on the TV, because they have moved the same mass over the same vertical distance, which requires the same amount of upward force. However, the woman using the pulley has generated more power. This is because she did the work in a shorter amount of time, so the denominator of the power formula, t , is smaller. (For simplicity’s sake, we will leave aside for now the fact that the man climbing the stairs has also done work on himself.)","Power can be expressed in units of watts (W). This unit can be used to measure power related to any form of energy or work. You have most likely heard the term used in relation to electrical devices, especially light bulbs. Multiplying power by time gives the amount of energy. Electricity is sold in kilowatt-hours because that equals the amount of electrical energy consumed.","The watt unit was named after James Watt (1736–1819) (see [Figure 9.1]). He was a Scottish engineer and inventor who discovered how to coax more power out of steam engines.","Before proceeding, be sure you understand the distinctions among force, work, energy, and power. Force exerted on an object over a distance does work. Work can increase energy, and energy can do work. Power is the rate at which work is done."],"figures":[{"sourceId":"fs-id1167064908163","filename":"CNX_HSPhysics_09_01_elevator.jpg","relativePath":"media/CNX_HSPhysics_09_01_elevator.jpg","alt":"A cross-section view of a four-story elevator is shown. The first three floors are labeled with h. A person is carrying a television up a flight of stairs on the second floor. Another person is standing on the ground floor, using a pulley to move a television up the floors."},{"sourceId":"fs-id1167065071601","filename":"CNX_HSPhysics_09_01_Watt.jpg","relativePath":"media/CNX_HSPhysics_09_01_Watt.jpg","alt":"A painting of James Watt is shown."}],"tables":[]}],"workedExamples":[{"uid":"hsphys.ch09.sec01.ex01","number":"9.1.1","title":"Applying the Work–Energy Theorem","problem":"An ice skater with a mass of 50 kg is gliding across the ice at a speed of 8 m/s when her friend comes up from behind and gives her a push, causing her speed to increase to 12 m/s. How much work did the friend do on the skater?","problemImages":[],"strategy":"The work–energy theorem can be applied to the problem. Write the equation for the theorem and simplify it if possible.\n\\(W = \\Delta \\text{KE =}\\frac{1}{2}m{\\mathbf{v}}_{2}^{2} - \\frac{1}{2}m{\\mathbf{v}}_{1}^{2}\\)\n\\(\\text{Simplify to}W = \\frac{1}{2}m({\\mathbf{v}}_{2}^{2} - {\\mathbf{v}}_{1}^{2})\\)","solution":"Identify the variables.\nm = 50 kg,\n\\({\\mathbf{v}}_{2} = 12\\frac{\\text{m}}{\\text{s}}\\text{, and}\\,{\\mathbf{v}}_{1} = 8\\frac{\\text{m}}{\\text{s}}\\) Substitute. \\(W = \\frac{1}{2}50({12}^{2} - {8}^{2}) = 2,000\\,\\text{J}\\)","solutionImages":[],"solutionTables":[],"discussion":"Work done on an object or system increases its energy. In this case, the increase is to the skater’s kinetic energy. It follows that the increase in energy must be the difference in KE before and after the push."}],"snapLabs":[],"tipsAndFeatures":[{"uid":"hsphys.ch09.sec01.feat01","type":"physics-in-action","title":"Watt’s Steam Engine","text":"James Watt did not invent the steam engine, but by the time he was finished tinkering with it, it was more useful. The first steam engines were not only inefficient, they only produced a back and forth, or reciprocal , motion. This was natural because pistons move in and out as the pressure in the chamber changes. This limitation was okay for simple tasks like pumping water or mashing potatoes, but did not work so well for moving a train. Watt was able build a steam engine that converted reciprocal motion to circular motion. With that one innovation, the industrial revolution was off and running. The world would never be the same. One of Watt's steam engines is shown in [Figure 9.1]. The video that follows the figure explains the importance of the steam engine in the industrial revolution.\nA late version of the Watt steam engine. (Nehemiah Hawkins, Wikimedia Commons)","images":[{"sourceId":"fs-id1167065877369","filename":"CNX_HSPhysics_09_02_stmengine.jpg","relativePath":"media/CNX_HSPhysics_09_02_stmengine.jpg","alt":"A black and white illustration of an early steam engine is shown."}]},{"uid":"hsphys.ch09.sec01.feat02","type":"tip","title":"Tips for Success","text":"This problem illustrates a general technique for approaching problems that require you to apply formulas: Identify the unknown and the known variables, express the unknown variables in terms of the known variables, and then enter all the known values.","images":[]}],"summaryPoints":["Doing work on a system or object changes its energy.","The work–energy theorem states that an amount of work that changes the velocity of an object is equal to the change in kinetic energy of that object.The work–energy theorem states that an amount of work that changes the velocity of an object is equal to the change in kinetic energy of that object.","Power is the rate at which work is done."],"glossary":[{"term":"energy","termVi":"Năng lượng (E)","definition":"the ability to do work","definitionVi":"Khả năng thực hiện công của một vật hoặc hệ vật (đơn vị J).","memoryTipVi":"Năng lượng không tự sinh ra hay mất đi, chỉ chuyển hóa từ dạng này sang dạng khác."},{"term":"gravitational potential energy","termVi":"Thế năng trọng trường (PE = mgh)","definition":"energy acquired by doing work against gravity","definitionVi":"Thế năng của vật ở độ cao h so với mốc: PE = mgh.","memoryTipVi":"Phụ thuộc vào mốc chọn h = 0."},{"term":"joule","termVi":"Jun (J)","definition":"the metric unit for work and energy; equal to 1 newton meter (N∙m)","definitionVi":"Đơn vị SI của Công và Năng lượng: 1 J = 1 N·m.","memoryTipVi":"Nâng quả táo 100g lên cao 1m tốn khoảng 1 J."},{"term":"kinetic energy","termVi":"Động năng (KE = ½mv²)","definition":"energy of motion","definitionVi":"Năng lượng vật có được do chuyển động: KE = ½mv² (vô hướng, luôn ≥ 0).","memoryTipVi":"Vận tốc tăng gấp 2 lần → Động năng tăng gấp 4 lần!"},{"term":"mechanical energy","termVi":"Cơ năng (ME = KE + PE)","definition":"kinetic or potential energy","definitionVi":"Tổng Động năng và Thế năng của vật.","memoryTipVi":"Cơ năng bảo toàn khi không có ma sát."},{"term":"power","termVi":"Công suất (P = W/t)","definition":"the rate at which work is done","definitionVi":"Tốc độ thực hiện công trong một đơn vị thời gian: P = W / t (đơn vị Watt, W).","memoryTipVi":"1 W = 1 J/s."},{"term":"potential energy","termVi":"Thế năng (PE)","definition":"stored energy","definitionVi":"Năng lượng dự trữ do vị trí hoặc trạng thái biến dạng của vật.","memoryTipVi":"Gồm Thế năng trọng trường và Thế năng đàn hồi."},{"term":"watt","termVi":"Oát (W)","definition":"the metric unit of power; equivalent to joules per second","definitionVi":"Đơn vị SI của công suất (1 W = 1 J/s).","memoryTipVi":"Đừng nhầm ký hiệu đơn vị W (Watt) với đại lượng W (Work - Công)!"},{"term":"work","termVi":"Công cơ học (W = F·d·cosθ)","definition":"force multiplied by distance","definitionVi":"Năng lượng truyền cho vật khi lực làm vật dịch chuyển: W = F·d·cosθ (đơn vị Joule, J).","memoryTipVi":"Lực vuông góc với chiều dịch chuyển (cos 90° = 0) thì Công = 0!"},{"term":"work–energy theorem","termVi":"Định lý Động năng (Công – Năng lượng)","definition":"states that the net work done on a system equals the change in kinetic energy","definitionVi":"Công của hợp lực tác dụng lên vật bằng độ biến thiên động năng: W_net = ΔKE.","memoryTipVi":"Rất hữu ích khi bài toán không cho thời gian t!"}],"assessments":[{"uid":"hsphys.ch09.sec01.q002","sourceId":"fs-id1167064896303","category":"check-understanding","categoryLabel":"Check Your Understanding (Kiểm tra đọc hiểu)","isMultipleChoice":true,"prompt":"When a coconut falls from a tree, work W is done on it as it falls to the beach. This work is described by the equation\n\\(W = Fd\\text{=}\\frac{1}{2}m{v}_{2}^{2} - \\frac{1}{2}m{v}_{1}^{2}.\\)\nIdentify the quantities F , d , m , v 1 , and v 2 in this event.","images":[],"choices":[{"label":"a","text":"F is the force of gravity, which is equal to the weight of the coconut, d is the distance the nut falls, m is the mass of the earth, v 1 is the initial velocity, and v 2 is the velocity with which it hits the beach."},{"label":"b","text":"F is the force of gravity, which is equal to the weight of the coconut, d is the distance the nut falls, m is the mass of the coconut, v 1 is the initial velocity, and v 2 is the velocity with which it hits the beach."},{"label":"c","text":"F is the force of gravity, which is equal to the weight of the coconut, d is the distance the nut falls, m is the mass of the earth, v 1 is the velocity with which it hits the beach, and v 2 is the initial velocity."},{"label":"d","text":"F is the force of gravity, which is equal to the weight of the coconut, d is the distance the nut falls, m is the mass of the coconut, v 1 is the velocity with which it hits the beach, and v 2 is the initial velocity."}],"hasOfficialSolution":false,"solution":null},{"uid":"hsphys.ch09.sec01.q007","sourceId":"eip-id1166851303586","category":"concept","categoryLabel":"Concept Items (Câu hỏi khái niệm)","isMultipleChoice":true,"prompt":"A book with a mass of 0.30 kg falls 2 m from a shelf to the floor. This event is described by the workenergy theorem: \\(W = fd\\text{=}\\frac{1}{2}m{v}_{2}^{2} - \\frac{1}{2}m{v}_{1}^{2}\\)\nExplain why this is enough information to calculate the speed with which the book hits the floor.","images":[],"choices":[{"label":"a","text":"The mass of the book, m , and distance, d , are stated. F is the weight of the book mg . v 1 is the initial velocity and v 2 is the final velocity. The final velocity is the only unknown quantity."},{"label":"b","text":"The mass of the book, m , and distance, d , are stated. F is the weight of the book mg . v 1 is the final velocity and v 2 is the initial velocity. The final velocity is the only unknown quantity."},{"label":"c","text":"The mass of the book, m , and distance, d , are stated. F is the weight of the book mg . v 1 is the initial velocity and v 2 is the final velocity. The final velocity and the initial velocities are the only unknown quantities."},{"label":"d","text":"The mass of the book, m , and distance, d , are stated. F is the weight of the book mg . v 1 is the final velocity and v 2 is the initial velocity. The final velocity and the initial velocities are the only unknown quantities."}],"hasOfficialSolution":false,"solution":null},{"uid":"hsphys.ch09.sec01.q008","sourceId":"fs-id1167066141722","category":"critical-thinking","categoryLabel":"Critical Thinking (Tư duy phản biện)","isMultipleChoice":true,"prompt":"Which activity requires a person to exert force on an object that causes the object to move but does not change the kinetic or potential energy of the object?","images":[],"choices":[{"label":"a","text":"Moving an object to a greater height with acceleration"},{"label":"b","text":"Moving an object to a greater height without acceleration"},{"label":"c","text":"Carrying an object with acceleration at the same height"},{"label":"d","text":"Carrying an object without acceleration at the same height"}],"hasOfficialSolution":false,"solution":null},{"uid":"hsphys.ch09.sec01.q009","sourceId":"eip-id1166848668634","category":"critical-thinking","categoryLabel":"Critical Thinking (Tư duy phản biện)","isMultipleChoice":true,"prompt":"Which statement explains how it is possible to carry books to school without changing the kinetic or potential energy of the books or doing any work?","images":[],"choices":[{"label":"a","text":"By moving the book without acceleration and keeping the height of the book constant"},{"label":"b","text":"By moving the book with acceleration and keeping the height of the book constant"},{"label":"c","text":"By moving the book without acceleration and changing the height of the book"},{"label":"d","text":"By moving the book with acceleration and changing the height of the book"}],"hasOfficialSolution":false,"solution":null},{"uid":"hsphys.ch09.sec01.q013","sourceId":"fs-id1167066139537","category":"problems","categoryLabel":"Problems (Bài toán tính toán)","isMultipleChoice":true,"prompt":"A boy pushes his little sister on a sled. The sled accelerates from 0 to 3.2 m/s . If the combined mass of his sister and\nthe sled is 40.0 kg and 18 W of power were generated, how long did the boy push the sled?","images":[],"choices":[{"label":"a","text":"205 s"},{"label":"b","text":"128 s"},{"label":"c","text":"23 s"},{"label":"d","text":"11 s"}],"hasOfficialSolution":false,"solution":null},{"uid":"hsphys.ch09.sec01.q015","sourceId":"fs-id1167062536704","category":"test-prep-mc","categoryLabel":"Test Prep — Trắc nghiệm","isMultipleChoice":true,"prompt":"The workenergy theorem states that the change in the kinetic energy of an object is equal to what?","images":[],"choices":[{"label":"a","text":"The work done on the object"},{"label":"b","text":"The force applied to the object"},{"label":"c","text":"The loss of the objects potential energy"},{"label":"d","text":"The objects total mechanical energy minus its kinetic energy"}],"hasOfficialSolution":false,"solution":null},{"uid":"hsphys.ch09.sec01.q016","sourceId":"eip-id1166851379573","category":"test-prep-mc","categoryLabel":"Test Prep — Trắc nghiệm","isMultipleChoice":true,"prompt":"A runner at the start of a race generates 250 W of power as he accelerates to 5 m/s . If the runner has a mass of 60 kg, how long did it take him to reach that speed?","images":[],"choices":[{"label":"a","text":"0.33 s"},{"label":"b","text":"0.83 s"},{"label":"c","text":"1.2 s"},{"label":"d","text":"3.0 s"}],"hasOfficialSolution":false,"solution":null},{"uid":"hsphys.ch09.sec01.q017","sourceId":"eip-id1166851398605","category":"test-prep-mc","categoryLabel":"Test Prep — Trắc nghiệm","isMultipleChoice":true,"prompt":"A cars engine generates 100,000 W of power as it exerts a force of 10,000 N. How long does it take the car to travel 100 m?","images":[],"choices":[{"label":"a","text":"0.001 s"},{"label":"b","text":"0.01 s"},{"label":"c","text":"10 s"},{"label":"d","text":"1,000 s"}],"hasOfficialSolution":false,"solution":null},{"uid":"hsphys.ch09.sec01.q019","sourceId":"fs-id1167065721266","category":"test-prep-sa","categoryLabel":"Test Prep — Trả lời ngắn","isMultipleChoice":true,"prompt":"True or falseWhile riding a bicycle up a gentle hill, it is fairly easy to increase your potential energy, but to increase your kinetic energy would make you feel exhausted.","images":[],"choices":[{"label":"a","text":"True"},{"label":"b","text":"False"}],"hasOfficialSolution":false,"solution":null},{"uid":"hsphys.ch09.sec01.q020","sourceId":"fs-id1167065858925","category":"test-prep-sa","categoryLabel":"Test Prep — Trả lời ngắn","isMultipleChoice":true,"prompt":"Which statement best explains why running on a track with constant speed at 3 m/s is not work, but climbing a mountain at 1 m/s is work?","images":[],"choices":[{"label":"a","text":"At constant speed, change in the kinetic energy is zero but climbing a mountain produces change in the potential energy."},{"label":"b","text":"At constant speed, change in the potential energy is zero, but climbing a mountain produces change in the kinetic energy."},{"label":"c","text":"At constant speed, change in the kinetic energy is finite, but climbing a mountain produces no change in the potential energy."},{"label":"d","text":"At constant speed, change in the potential energy is finite, but climbing a mountain produces no change in the kinetic energy."}],"hasOfficialSolution":false,"solution":null},{"uid":"hsphys.ch09.sec01.q022","sourceId":"fs-id1167066095434","category":"test-prep-er","categoryLabel":"Test Prep — Tự luận mở rộng","isMultipleChoice":true,"prompt":"Work can be negative as well as positive because an object or system can do work on its surroundings as well as have work done on it. Which of the following statements describes:\na situation in which an object does work on its surroundings by decreasing its velocity and\na situation in which an object can do work on its surroundings by decreasing its altitude?","images":[],"choices":[{"label":"a","text":"A gasoline engine burns less fuel at a slower speed.\nSolar cells capture sunlight to generate electricity."},{"label":"b","text":"A hybrid car charges its batteries as it decelerates.\nFalling water turns a turbine to generate electricity."},{"label":"c","text":"Airplane flaps use air resistance to slow down for landing.\nRising steam turns a turbine to generate electricity."},{"label":"d","text":"An electric train requires less electrical energy as it decelerates.\nA parachute captures air to slow a skydivers fall."}],"hasOfficialSolution":false,"solution":null},{"uid":"hsphys.ch09.sec01.q023","sourceId":"fs-id1167062971594","category":"test-prep-er","categoryLabel":"Test Prep — Tự luận mở rộng","isMultipleChoice":true,"prompt":"A boy is pulling a girl in a childs wagon at a constant speed. He begins to pull harder, which increases the speed of the wagon. Which of the following describes two ways you could calculate the change in energy of the wagon and girl if you had all the information you needed?","images":[],"choices":[{"label":"a","text":"Calculate work done from the force and the velocity.\nCalculate work done from the change in the potential energy of the system."},{"label":"b","text":"Calculate work done from the force and the displacement.\nCalculate work done from the change in the potential energy of the system."},{"label":"c","text":"Calculate work done from the force and the velocity.\nCalculate work done from the change in the kinetic energy of the system."},{"label":"d","text":"Calculate work done from the force and the displacement.\nCalculate work done from the change in the kinetic energy of the system."}],"hasOfficialSolution":false,"solution":null}],"stats":{"learningObjectiveCount":2,"keyEquationCount":6,"subsectionCount":2,"workedExampleCount":1,"snapLabCount":0,"glossaryCount":10,"assessmentCount":12}},{"uid":"hsphys.ch09.sec02","moduleId":"m54273","number":"9.2","slug":"mechanical-energy-and-conservation-of-energy","title":"Mechanical Energy and Conservation of Energy","isIntroduction":false,"learningObjectives":["Explain the law of conservation of energy in terms of kinetic and potential energy","Perform calculations related to kinetic and potential energy. Apply the law of conservation of energy"],"bilingualGuide":{"notebookSummaryVi":"Định luật Bảo toàn Cơ năng (KE_i + PE_i = KE_f + PE_f khi bỏ qua ma sát) và sự chuyển hóa năng lượng.","wordProblemCues":[{"phraseEn":"frictionless / conserved","meaningVi":"Không ma sát → Cơ năng bảo toàn","mathNotation":"KE + PE = const"}],"commonTrapsVi":["Nhớ quy ước rõ mốc thế năng h = 0 (thường chọn ở vị trí thấp nhất của bài toán)."]},"keyEquations":[{"name":"conservation of energy","formula":"\\(K{E}_{1} + P{E}_{1} = K{E}_{2} + P{E}_{2}\\)"}],"subsections":[{"uid":"hsphys.ch09.sec02.sub01","title":"Mechanical Energy and Conservation of Energy","summaryVi":null,"paragraphs":["We saw earlier that mechanical energy can be either potential or kinetic. In this section we will see how energy is transformed from one of these forms to the other. We will also see that, in a closed system, the sum of these forms of energy remains constant.","Quite a bit of potential energy is gained by a roller coaster car and its passengers when they are raised to the top of the first hill. Remember that the potential part of the term means that energy has been stored and can be used at another time. You will see that this stored energy can either be used to do work or can be transformed into kinetic energy. For example, when an object that has gravitational potential energy falls, its energy is converted to kinetic energy. Remember that both work and energy are expressed in joules.","Refer back to [Figure 9.1]. The amount of work required to raise the TV from point A to point B is equal to the amount of gravitational potential energy the TV gains from its height above the ground. This is generally true for any object raised above the ground. If all the work done on an object is used to raise the object above the ground, the amount of work equals the object’s gain in gravitational potential energy. However, note that because of the work done by friction, these energy–work transformations are never perfect. Friction causes the loss of some useful energy. In the discussions to follow, we will use the approximation that transformations are frictionless.","Now, let’s look at the roller coaster in [Figure 9.2]. Work was done on the roller coaster to get it to the top of the first rise; at this point, the roller coaster has gravitational potential energy. It is moving slowly, so it also has a small amount of kinetic energy. As the car descends the first slope, its PE is converted to KE . At the low point much of the original PE has been transformed to KE , and speed is at a maximum. As the car moves up the next slope, some of the KE is transformed back into PE and the car slows down.","This simulation shows how kinetic and potential energy are related, in a scenario similar to the roller coaster. Observe the changes in KE and PE by clicking on the bar graph boxes. Also try the three differently shaped skate parks. Drag the skater to the track to start the animation.","On an actual roller coaster, there are many ups and downs, and each of these is accompanied by transitions between kinetic and potential energy. Assume that no energy is lost to friction. At any point in the ride, the total mechanical energy is the same, and it is equal to the energy the car had at the top of the first rise. This is a result of the law of conservation of energy , which says that, in a closed system, total energy is conservedthat is, it is constant. Using subscripts 1 and 2 to represent initial and final energy, this law is expressed as","Either side equals the total mechanical energy. The phrase in a closed system means we are assuming no energy is lost to the surroundings due to friction and air resistance. If we are making calculations on dense falling objects, this is a good assumption. For the roller coaster, this assumption introduces some inaccuracy to the calculation."],"figures":[{"sourceId":"fs-id1167065023046","filename":"CNX_HSPhysics_09_02_coaster.jpg","relativePath":"media/CNX_HSPhysics_09_02_coaster.jpg","alt":"An illustration shows a side view of a roller coaster. People in a cart are at the top of a hill, and the cart is labeled Start. The cart is heading towards a downward slope. The opposite end of the roller coaster is flat and is labeled Finish."}],"tables":[]}],"workedExamples":[{"uid":"hsphys.ch09.sec02.ex01","number":"9.2.1","title":"Applying the Law of Conservation of Energy","problem":"A 10 kg rock falls from a 20 m cliff. What is the kinetic and potential energy when the rock has fallen 10 m?","problemImages":[],"strategy":"Choose the equation.\n\\(K{E}_{1} + P{E}_{1} = K{E}_{2} + P{E}_{2}\\)\n\\(KE = \\frac{1}{2}m{\\mathbf{v}}_{}^{2};PE = m\\mathbf{g}h\\)\n\\(\\frac{1}{2}m{\\mathbf{v}}_{1}^{2} + m\\mathbf{g}{h}_{1} = \\frac{1}{2}m{\\mathbf{v}}_{2}^{2} + m\\mathbf{g}{h}_{2}\\)\nList the knowns.\nm = 10 kg, v 1 = 0, g = 9.80\n\\(\\frac{\\text{m}}{{\\text{s}}^{2}}\\text{,}\\) h 1 = 20 m, h 2 = 10 m\nIdentify the unknowns.\nKE 2 and PE 2\nSubstitute the known values into the equation and solve for the unknown variables.","solution":"\\(P{E}_{2} = m\\mathbf{g}{h}_{2} = 10(9.80)10 = 980\\,\\text{J}\\)\n\\(K{E}_{2} = P{E}_{2} - (K{E}_{1} + P{E}_{1}) = 980 - {[0 - [10(9.80)20]]} = 980\\,\\text{J}\\)","solutionImages":[],"solutionTables":[],"discussion":"Alternatively, conservation of energy equation could be solved for v 2 and KE 2 could be calculated. Note that m could also be eliminated.\nNote that we can solve many problems involving conversion between KE and PE without knowing the mass of the object in question. This is because kinetic and potential energy are both proportional to the mass of the object. In a situation where KE = PE , we know that m g h = (1/2) m v 2 .\nDividing both sides by m and rearranging, we have the relationship\n2 g h = v 2 ."}],"snapLabs":[{"uid":"hsphys.ch09.sec02.lab01","title":"Converting Potential Energy to Kinetic Energy","text":"In this activity, you will calculate the potential energy of an object and predict the object’s speed when all that potential energy has been converted to kinetic energy. You will then check your prediction.\nYou will be dropping objects from a height. Be sure to stay a safe distance from the edge. Don’t lean over the railing too far. Make sure that you do not drop objects into an area where people or vehicles pass by. Make sure that dropping objects will not cause damage.\nYou will need the following:\nMaterials for each pair of students:\nFour marbles (or similar small, dense objects)\nStopwatch\nMaterials for class:\nMetric measuring tape long enough to measure the chosen height\nA scale\nInstructions\nProcedure\nWork with a partner. Find and record the mass of four small, dense objects per group.\nChoose a location where the objects can be safely dropped from a height of at least 15 meters. A bridge over water with a safe pedestrian walkway will work well.\nMeasure the distance the object will fall.\nCalculate the potential energy of the object before you drop it using PE = m g h = (9.80) mh.\nPredict the kinetic energy and velocity of the object when it lands using PE = KE and so, \\(m\\mathbf{g}h = \\frac{m{\\mathbf{v}}^{2}}{2};\\mathbf{v} = \\sqrt{2(9.80)h} = 4.43\\sqrt{h}\\text{.}\\)\nOne partner drops the object while the other measures the time it takes to fall.\nTake turns being the dropper and the timer until you have made four measurements.\nAverage your drop multiplied by and calculate the velocity of the object when it landed using v = a t = g t = (9.80) t .\nCompare your results to your prediction.","images":[]}],"tipsAndFeatures":[{"uid":"hsphys.ch09.sec02.feat01","type":"tip","title":"Tips for Success","text":"When calculating work or energy, use units of meters for distance, newtons for force, kilograms for mass, and seconds for time. This will assure that the result is expressed in joules.","images":[]},{"uid":"hsphys.ch09.sec02.feat02","type":"tip","title":"Tips for Success","text":"Note that we can solve many problems involving conversion between KE and PE without knowing the mass of the object in question. This is because kinetic and potential energy are both proportional to the mass of the object. In a situation where KE = PE , we know that m g h = (1/2) m v 2 .\nDividing both sides by m and rearranging, we have the relationship\n2 g h = v 2 .","images":[]}],"summaryPoints":["Mechanical energy may be either kinetic (energy of motion) or potential (stored energy).","Doing work on an object or system changes its energy.","Total energy in a closed, isolated system is constant."],"glossary":[{"term":"law of conservation of energy","termVi":"Định luật Bảo toàn Năng lượng","definition":"states that energy is neither created nor destroyed","definitionVi":"Tổng năng lượng của một hệ cô lập luôn không đổi: KE_i + PE_i = KE_f + PE_f (khi không ma sát).","memoryTipVi":"Công cụ giải bài nhanh gấp 3 lần dùng Newton!"}],"assessments":[{"uid":"hsphys.ch09.sec02.q002","sourceId":"fs-id1167065809139","category":"check-understanding","categoryLabel":"Check Your Understanding (Kiểm tra đọc hiểu)","isMultipleChoice":true,"prompt":"True or falseIf a rock is thrown into the air, the increase in the height would increase the rocks kinetic energy, and then the increase in the velocity as it falls to the ground would increase its potential energy.","images":[],"choices":[{"label":"a","text":"True"},{"label":"b","text":"False"}],"hasOfficialSolution":false,"solution":null},{"uid":"hsphys.ch09.sec02.q003","sourceId":"eip-id1166850259590","category":"check-understanding","categoryLabel":"Check Your Understanding (Kiểm tra đọc hiểu)","isMultipleChoice":true,"prompt":"Identify equivalent terms for stored energy and energy of motion .","images":[],"choices":[{"label":"a","text":"Stored energy is potential energy, and energy of motion is kinetic energy."},{"label":"b","text":"Energy of motion is potential energy, and stored energy is kinetic energy."},{"label":"c","text":"Stored energy is the potential as well as the kinetic energy of the system."},{"label":"d","text":"Energy of motion is the potential as well as the kinetic energy of the system."}],"hasOfficialSolution":false,"solution":null},{"uid":"hsphys.ch09.sec02.q004","sourceId":"fs-id1167066094212","category":"practice-problems","categoryLabel":"Practice Problems (Bài tập vận dụng)","isMultipleChoice":true,"prompt":"A child slides down a playground slide. If the slide is 3 m high and the child weighs 300 N, how much potential energy does the child have at the top of the slide? (Round g to \\(10\\,m/{s}^{2}.\\) )","images":[],"choices":[{"label":"a","text":"0 J"},{"label":"b","text":"100 J"},{"label":"c","text":"300 J"},{"label":"d","text":"900 J"}],"hasOfficialSolution":false,"solution":null},{"uid":"hsphys.ch09.sec02.q005","sourceId":"fs-id1167065948878","category":"practice-problems","categoryLabel":"Practice Problems (Bài tập vận dụng)","isMultipleChoice":true,"prompt":"A 0.2 kg apple on an apple tree has a potential energy of 10 J. It falls to the ground, converting all of its PE to kinetic energy. What is the velocity of the apple just before it hits the ground?","images":[],"choices":[{"label":"a","text":"0 m/s"},{"label":"b","text":"2 m/s"},{"label":"c","text":"10 m/s"},{"label":"d","text":"50 m/s"}],"hasOfficialSolution":false,"solution":null},{"uid":"hsphys.ch09.sec02.q009","sourceId":"eip-id1166850144882","category":"concept","categoryLabel":"Concept Items (Câu hỏi khái niệm)","isMultipleChoice":true,"prompt":"The starting line of a cross country foot race is at the bottom of a hill. Which form(s) of mechanical energy of the runners will change when the starting gun is fired?","images":[],"choices":[{"label":"a","text":"Kinetic energy only"},{"label":"b","text":"Potential energy only"},{"label":"c","text":"Both kinetic and potential energy"},{"label":"d","text":"Neither kinetic nor potential energy"}],"hasOfficialSolution":false,"solution":null},{"uid":"hsphys.ch09.sec02.q010","sourceId":"fs-id1167065848516","category":"critical-thinking","categoryLabel":"Critical Thinking (Tư duy phản biện)","isMultipleChoice":true,"prompt":"True or falseA cyclist coasts down one hill and up another hill until she comes to a stop. The point at which the bicycle stops is lower than the point at which it started coasting because part of the original potential energy has been converted to a quantity of heat and this makes the tires of the bicycle warm.","images":[],"choices":[{"label":"a","text":"True"},{"label":"b","text":"False"}],"hasOfficialSolution":false,"solution":null},{"uid":"hsphys.ch09.sec02.q011","sourceId":"fs-id1167066094212","category":"problems","categoryLabel":"Problems (Bài toán tính toán)","isMultipleChoice":true,"prompt":"A child slides down a playground slide. If the slide is 3 m high and the child weighs 300 N, how much potential energy does the child have at the top of the slide? (Round g to \\(10\\,m/{s}^{2}.\\) )","images":[],"choices":[{"label":"a","text":"0 J"},{"label":"b","text":"100 J"},{"label":"c","text":"300 J"},{"label":"d","text":"900 J"}],"hasOfficialSolution":false,"solution":null},{"uid":"hsphys.ch09.sec02.q012","sourceId":"fs-id1167065948878","category":"problems","categoryLabel":"Problems (Bài toán tính toán)","isMultipleChoice":true,"prompt":"A 0.2 kg apple on an apple tree has a potential energy of 10 J. It falls to the ground, converting all of its PE to kinetic energy. What is the velocity of the apple just before it hits the ground?","images":[],"choices":[{"label":"a","text":"0 m/s"},{"label":"b","text":"2 m/s"},{"label":"c","text":"10 m/s"},{"label":"d","text":"50 m/s"}],"hasOfficialSolution":false,"solution":null},{"uid":"hsphys.ch09.sec02.q016","sourceId":"fs-id1163727091588","category":"problems","categoryLabel":"Problems (Bài toán tính toán)","isMultipleChoice":true,"prompt":"The potential energy stored in a compressed spring is \\(U = \\frac{1}{2}k{x}^{2}\\), where k is the force constant and x is the distance the spring is compressed from the equilibrium position. Four experimental setups described below can be used to determine the force constant of a spring. Which one(s) require measurement of the fewest number of variables to determine k ? Assume the acceleration due to gravity is known.\nAn object is propelled vertically by a compressed spring.\nAn object is propelled horizontally on a frictionless surface by a compressed spring.\nAn object is statically suspended from a spring.\nAn object suspended from a spring is set into oscillatory motion.","images":[],"choices":[{"label":"a","text":"I only"},{"label":"b","text":"III only"},{"label":"c","text":"I and II only"},{"label":"d","text":"III and IV only"}],"hasOfficialSolution":true,"solution":"The correct answer is (d), which features two setups where two quantities must be measured to find the spring constant. The period of an object suspended from a spring is determined by the mass of the object and the spring constant \\((T = 2\\pi \\sqrt{m/k})\\), so only the mass and period need to be measured to find the force constant, k . The distance x a spring stretches when an object is suspended from it can be determined by the equation \\(mg = kx\\), so only the mass and the distance need to be measured to find k . The remaining two arrangements require measurement of three quantities: the mass and a displacement plus either a height or a speed, since (I) is described by the equation \\(mgh = \\frac{1}{2}k{x}^{2}\\) and (II) is described by the equation \\(\\frac{1}{2}k{x}^{2} = \\frac{1}{2}m{v}^{2}\\) ."},{"uid":"hsphys.ch09.sec02.q021","sourceId":"fs-id1167065822816","category":"test-prep-sa","categoryLabel":"Test Prep — Trả lời ngắn","isMultipleChoice":true,"prompt":"True or falseThe formula for gravitational potential energy can be used to explain why joules, J, are equivalent to kg × m 2 / s 2 . Show your work.","images":[],"choices":[{"label":"a","text":"True"},{"label":"b","text":"False"}],"hasOfficialSolution":false,"solution":null},{"uid":"hsphys.ch09.sec02.q024","sourceId":"fs-id1167065770876","category":"test-prep-sa","categoryLabel":"Test Prep — Trả lời ngắn","isMultipleChoice":true,"prompt":"True or falseA marble rolls down a slope from height h 1 and up another slope to height h 2 , where ( h 2 < h 1 ). The difference mg ( h 1  h 2 ) is equal to the heat lost due to the friction.","images":[],"choices":[{"label":"a","text":"True"},{"label":"b","text":"False"}],"hasOfficialSolution":false,"solution":null},{"uid":"hsphys.ch09.sec02.q025","sourceId":"fs-id1167065853524","category":"test-prep-er","categoryLabel":"Test Prep — Tự luận mở rộng","isMultipleChoice":true,"prompt":"Acceleration due to gravity on the moon is 1.6 m/s 2 or about 16% of the value of g on Earth.\nIf an astronaut on the moon threw a moon rock to a height of 7.8 m, what would be its velocity as it struck the\nmoons surface?\nHow would the fact that the moon has no atmosphere affect the velocity of the falling moon rock? Explain your\nanswer.","images":[],"choices":[{"label":"a","text":"The velocity of the rock as it hits the ground would be 5.0 m/s. Due to the lack of air friction, there would be complete transformation of the potential energy into the kinetic energy as the rock hits the moons surface."},{"label":"b","text":"The velocity of the rock as it hits the ground would be 5.0 m/s. Due to the lack of air friction, there would be incomplete transformation of the potential energy into the kinetic energy as the rock hits the moons surface."},{"label":"c","text":"The velocity of the rock as it hits the ground would be 12 m/s. Due to the lack of air friction, there would be complete transformation of the potential energy into the kinetic energy as the rock hits the moons surface."},{"label":"d","text":"The velocity of the rock as it hits the ground would be 12 m/s. Due to the lack of air friction, there would be incomplete transformation of the potential energy into the kinetic energy as the rock hits the moons surface."}],"hasOfficialSolution":false,"solution":null}],"stats":{"learningObjectiveCount":2,"keyEquationCount":1,"subsectionCount":1,"workedExampleCount":1,"snapLabCount":1,"glossaryCount":1,"assessmentCount":12}},{"uid":"hsphys.ch09.sec03","moduleId":"m54274","number":"9.3","slug":"simple-machines","title":"Simple Machines","isIntroduction":false,"learningObjectives":["Describe simple and complex machines","Calculate mechanical advantage and efficiency of simple and complex machines"],"bilingualGuide":{"notebookSummaryVi":"6 loại Máy cơ đơn giản (Đòn bẩy, Ròng rọc, Mặt phẳng nghiêng, Nêm, Vít, Bánh xe & trục), Lợi ích cơ học (MA / IMA) và Hiệu suất (Efficiency).","wordProblemCues":[{"phraseEn":"efficiency","meaningVi":"Hiệu suất = (Công có ích / Công toàn phần) × 100%","mathNotation":"Eff = W_out / W_in"}],"commonTrapsVi":["Không có máy cơ nào cho lợi về CÔNG (vì W_out ≤ W_in) — máy chỉ cho lợi về LỰC hoặc hướng lực!"]},"keyEquations":[{"name":"ideal mechanical advantage (general)","formula":"\\(IMA = \\frac{{\\text{F}}_{r}}{{\\text{F}}_{e}} = \\frac{{d}_{e}}{{d}_{r}}\\)"},{"name":"ideal mechanical advantage (lever)","formula":"\\(IMA = \\frac{{L}_{e}}{{L}_{r}}\\)"},{"name":"ideal mechanical advantage (wheel and axle)","formula":"\\(IMA = \\frac{R}{r}\\)"},{"name":"ideal mechanical advantage (inclined plane)","formula":"\\(IMA = \\frac{L}{h}\\)"},{"name":"ideal mechanical advantage (wedge)","formula":"\\(IMA = \\frac{L}{t}\\)"},{"name":"ideal mechanical advantage (pulley)","formula":"\\(IMA = N\\)"},{"name":"ideal mechanical advantage (screw)","formula":"\\(IMA = \\frac{2\\pi L}{P}\\)"},{"name":"input work","formula":"\\({W}_{i} = {\\mathbf{F}}_{i}{d}_{i}\\)"},{"name":"output work","formula":"\\({W}_{o} = {\\mathbf{F}}_{o}{d}_{o}\\)"},{"name":"efficiency output","formula":"\\(%\\text{efficiency} = \\frac{{W}_{o}}{{W}_{i}} \\times 100\\)"}],"subsections":[{"uid":"hsphys.ch09.sec03.sub01","title":"Simple Machines","summaryVi":null,"paragraphs":["Simple machines make work easier, but they do not decrease the amount of work you have to do. Why can’t simple machines change the amount of work that you do? Recall that in closed systems the total amount of energy is conserved. A machine cannot increase the amount of energy you put into it. So, why is a simple machine useful? Although it cannot change the amount of work you do, a simple machine can change the amount of force you must apply to an object, and the distance over which you apply the force. In most cases, a simple machine is used to reduce the amount of force you must exert to do work. The down side is that you must exert the force over a greater distance, because the product of force and distance, f d , (which equals work) does not change.","Let’s examine how this works in practice. In [Figure 9.3](a), the worker uses a type of lever to exert a small force over a large distance, while the pry bar pulls up on the nail with a large force over a small distance. [Figure 9.3](b) shows how a lever works mathematically. The effort force, applied at F e , lifts the load (the resistance force) which is pushing down at F r . The triangular pivot is called the fulcrum ; the part of the lever between the fulcrum and F e is the effort arm, L e ; and the part to the left is the resistance arm, L r . The mechanical advantage is a number that tells us how many times a simple machine multiplies the effort force. The ideal mechanical advantage , IMA , is the mechanical advantage of a perfect machine with no loss of useful work caused by friction between moving parts. The equation for IMA is shown in [Figure 9.3](b).","In general, the IMA = the resistance force, F r , divided by the effort force, F e . IMA also equals the distance over which the effort is applied, d e , divided by the distance the load travels, d r .","Getting back to conservation of energy, for any simple machine, the work put into the machine, W i , equals the work the machine puts out, W o . Combining this with the information in the paragraphs above, we can write","The equations show how a simple machine can output the same amount of work while reducing the amount of effort force by increasing the distance over which the effort force is applied.","Some levers exert a large force to a short effort arm. This results in a smaller force acting over a greater distance at the end of the resistance arm. Examples of this type of lever are baseball bats, hammers, and golf clubs. In another type of lever, the fulcrum is at the end of the lever and the load is in the middle, as in the design of a wheelbarrow.","The simple machine shown in [Figure 9.3] is called a wheel and axle . It is actually a form of lever. The difference is that the effort arm can rotate in a complete circle around the fulcrum, which is the center of the axle. Force applied to the outside of the wheel causes a greater force to be applied to the rope that is wrapped around the axle. As shown in the figure, the ideal mechanical advantage is calculated by dividing the radius of the wheel by the radius of the axle. Any crank-operated device is an example of a wheel and axle.","An inclined plane and a wedge are two forms of the same simple machine. A wedge is simply two inclined planes back to back. [Figure 9.3] shows the simple formulas for calculating the IMA s of these machines. All sloping, paved surfaces for walking or driving are inclined planes. Knives and axe heads are examples of wedges.","The screw shown in [Figure 9.3] is actually a lever attached to a circular inclined plane. Wood screws (of course) are also examples of screws. The lever part of these screws is a screw driver. In the formula for IMA , the distance between screw threads is called pitch and has the symbol P .","[Figure 9.3] shows three different pulley systems. Of all simple machines, mechanical advantage is easiest to calculate for pulleys. Simply count the number of ropes supporting the load. That is the IMA . Once again we have to exert force over a longer distance to multiply force. To raise a load 1 meter with a pulley system you have to pull N meters of rope. Pulley systems are often used to raise flags and window blinds and are part of the mechanism of construction cranes.","A complex machine is a combination of two or more simple machines. The wire cutters in [Figure 9.3] combine two levers and two wedges. Bicycles include wheel and axles, levers, screws, and pulleys. Cars and other vehicles are combinations of many machines."],"figures":[{"sourceId":"fs-id1167066809531","filename":"CNX_HSPhysics_09_03_levers.jpg","relativePath":"media/CNX_HSPhysics_09_03_levers.jpg","alt":"Two diagrams are shown side by side. The diagram on the left shows a drawing of a hand pulling a mail out of wood using a lever. The diagram on the right shows an illustration of a lever and a fulcrum. The fulcrum is closer to the left side of the lever than the right side. The distance of the left side of the lever is labeled L subscript r and the distance of the right side is labeled L subscript e. A force vector is pointing down on the left side and is labeled F subscript r, and a force vector is pointing down on the right side and is labeled F subscript e. The equation IMA equals L subscript e over L subscript r is also shown."},{"sourceId":"fs-id1167067084955","filename":"CNX_HSPhysics_09_03_wheel.jpg","relativePath":"media/CNX_HSPhysics_09_03_wheel.jpg","alt":"A diagram of a wheel is shown. The equation IMA equals capital R over lowercase r. A small grey circle is inside a larger blue circle. An arrow labeled lowercase r points from the center of the smaller circle to its edge. An arrow labeled capital R points from the center of the smaller circle to the edge of the larger circle. A mass is attached to the smaller circle and has a force vector, F subscript r, pointing downward from it. Another force vector, F subscript e, points downward and to the right from the edge of the larger circle."},{"sourceId":"fs-id1167066783636","filename":"CNX_HSPhysics_09_03_wedge.jpg","relativePath":"media/CNX_HSPhysics_09_03_wedge.jpg","alt":"Two diagrams are shown side-by-side. On the left, an inclined plane is shown. Its horizontal surface distance is labeled L and its height is labeled h. A box is shown on the surface with a force vector that points up the plane. The equation IMA equals L over h is shown. On the right, a wedge is shown. Its horizontal surface distance is labeled L. Its height is labeled t. The equation IMA equals L over t is also shown."},{"sourceId":"fs-id1167067158213","filename":"CNX_HSPhysics_09_03_screw.jpg","relativePath":"media/CNX_HSPhysics_09_03_screw.jpg","alt":"An illustration of a screw is shown. It has a long lever, labeled L. P is pitch, the distance between the threads."},{"sourceId":"fs-id1167067090823","filename":"CNX_HSPhysics_09_03_pulleys.jpg","relativePath":"media/CNX_HSPhysics_09_03_pulleys.jpg","alt":"Three pulley systems are shown in side-by-side diagrams. The first consists of a single pulley and is shown holding a mass. The mass is labeled with a force vector, F r, that also points downward. Another force vector, F e, is shown pointing downward from the pulley. N equals one is also shown. The second pulley system consists of a single pulley holding a mass. A force vector, F e, points upward from the pulley. N equals two is shown. The last pulley system shows four pulleys holding a mass with a hook. A force vector, F e, points downward from the pulley. N equals four is shown."},{"sourceId":"fs-id1167066839319","filename":"CNX_HSPhysics_09_03_wirecutter.jpg","relativePath":"media/CNX_HSPhysics_09_03_wirecutter.jpg","alt":"An illustration shows a pair of hand-held wire cutters."}],"tables":[]},{"uid":"hsphys.ch09.sec03.sub02","title":"Calculating Mechanical Advantage and Efficiency of Simple Machines","summaryVi":null,"paragraphs":["In general, the IMA = the resistance force, F r , divided by the effort force, F e . IMA also equals the distance over which the effort is applied, d e , divided by the distance the load travels, d r .","Refer back to the discussions of each simple machine for the specific equations for the IMA for each type of machine.","No simple or complex machines have the actual mechanical advantages calculated by the IMA equations. In real life, some of the applied work always ends up as wasted heat due to friction between moving parts. Both the input work ( W i ) and output work ( W o ) are the result of a force, F , acting over a distance, d .","The efficiency output of a machine is simply the output work divided by the input work, and is usually multiplied by 100 so that it is expressed as a percent.","Look back at the pictures of the simple machines and think about which would have the highest efficiency. Efficiency is related to friction, and friction depends on the smoothness of surfaces and on the area of the surfaces in contact. How would lubrication affect the efficiency of a simple machine?"],"figures":[],"tables":[]},{"uid":"hsphys.ch09.sec03.sub03","title":"Performance Task","summaryVi":null,"paragraphs":["Conservation of Energy and Energy Transfer; Cause and Effect; and S&EP, Planning and Carrying Out Investigations","Plan an investigation to measure the mechanical advantage of simple machines and compare to the IMA of the machine. Also measure the efficiency of each machine studied. Design an investigation to make these measurements for these simple machines: lever, inclined plane, wheel and axle and a pulley system. In addition to these machines, include a spring scale, a tape measure, and a weight with a loop on top that can be attached to the hook on the spring scale. A spring scale is shown in the image.","A spring scale measures weight, not mass.","LEVER: Beginning with the lever, explain how you would measure input force, output force, effort arm, and resistance arm. Also explain how you would find the distance the load travels and the distance over which the effort force is applied. Explain how you would use this data to determine IMA and efficiency.","INCLINED PLANE: Make measurements to determine IMA and efficiency of an inclined plane. Explain how you would use the data to calculate these values. Which property do you already know? Note that there are no effort and resistance arm measurements, but there are height and length measurements.","WHEEL AND AXLE: Again, you will need two force measurements and four distance measurements. Explain how you would use these to calculate IMA and efficiency.","SCREW: You will need two force measurements, two distance traveled measurements, and two length measurements. You may describe a screw like the one shown in [Figure 9.3] or you could use a screw and screw driver. (Measurements would be easier for the former). Explain how you would use these to calculate IMA and efficiency.","PULLEY SYSTEM: Explain how you would determine the IMA and efficiency of the four-pulley system shown in [Figure 9.3]. Why do you only need two distance measurements for this machine?","Design a table that compares the efficiency of the five simple machines. Make predictions as to the most and least efficient machines."],"figures":[{"sourceId":"fs-id1167063785811","filename":"CNX_HSPhysics_09_03_scale_img.jpg","relativePath":"media/CNX_HSPhysics_09_03_scale_img.jpg","alt":"An illustration of a spring scale is shown. The left side shows grams and the right side shows Newtons."}],"tables":[]}],"workedExamples":[{"uid":"hsphys.ch09.sec03.ex01","number":"9.3.1","title":"Efficiency of a Lever","problem":"The input force of 11 N acting on the effort arm of a lever moves 0.4 m, which lifts a 40 N weight resting on the resistance arm a distance of 0.1 m. What is the efficiency of the machine?","problemImages":[],"strategy":"State the equation for efficiency of a simple machine, \\(%\\text{efficiency} = \\frac{{W}_{o}}{{W}_{i}} \\times 100\\text{,}\\) and calculate W o and W i . Both work values are the product Fd .","solution":"\\({W}_{i} = {\\mathbf{F}}_{i}{d}_{i}\\) = (11)(0.4) = 4.4 J and \\({W}_{o} = {\\mathbf{F}}_{o}{d}_{o}\\) = (40)(0.1) = 4.0 J, then \\(%\\text{efficiency} = \\frac{{W}_{o}}{{W}_{i}} \\times 100 = \\frac{4.0}{4.4} \\times 100 = 91%\\)","solutionImages":[],"solutionTables":[],"discussion":"Efficiency in real machines will always be less than 100 percent because of work that is converted to unavailable heat by friction and air resistance. W o and W i can always be calculated as a force multiplied by a distance, although these quantities are not always as obvious as they are in the case of a lever."}],"snapLabs":[],"tipsAndFeatures":[],"summaryPoints":["The six types of simple machines make work easier by changing the f d term so that force is reduced at the expense of increased distance.","The ratio of output force to input force is a machine’s mechanical advantage.","Combinations of two or more simple machines are called complex machines.","The ratio of output work to input work is a machine’s efficiency."],"glossary":[{"term":"complex machine","termVi":"Máy cơ phức hợp","definition":"a machine that combines two or more simple machines","definitionVi":"Máy ghép từ hai hay nhiều máy cơ đơn giản (như xe đạp, kéo cắt).","memoryTipVi":"Lợi ích cơ học bằng tích các máy thành phần."},{"term":"efficiency","termVi":"Hiệu suất (H)","definition":"output work divided by input work","definitionVi":"Tỉ số giữa công có ích và công toàn phần (luôn < 100% do ma sát): Eff = (W_out / W_in) × 100%.","memoryTipVi":"Hiệu suất thực tế không bao giờ vượt quá 100%."},{"term":"ideal mechanical advantage","termVi":"Lợi ích cơ học lý tưởng (IMA)","definition":"the mechanical advantage of an idealized machine that loses no energy to friction","definitionVi":"Lợi ích cơ học khi bỏ qua hoàn toàn ma sát: IMA = d_in / d_out.","memoryTipVi":"MA thực tế luôn nhỏ hơn IMA."},{"term":"inclined plane","termVi":"Mặt phẳng nghiêng","definition":"a simple machine consisting of a slope","definitionVi":"Mặt dốc nghiêng giúp đẩy vật lên cao nhẹ hơn nâng thẳng đứng.","memoryTipVi":"IMA = Chiều dài dốc / Chiều cao."},{"term":"input work","termVi":"Công toàn phần / Công đầu vào (W_in)","definition":"effort force multiplied by the distance over which it is applied","definitionVi":"Công do người/động cơ bỏ ra tác dụng vào máy.","memoryTipVi":"W_in = F_in · d_in."},{"term":"lever","termVi":"Đòn bẩy","definition":"a simple machine consisting of a rigid arm that pivots on a fulcrum","definitionVi":"Thanh cứng quay quanh một điểm tựa (fulcrum).","memoryTipVi":"Cánh tay đòn lực càng dài càng lợi về lực."},{"term":"mechanical advantage","termVi":"Lợi ích cơ học thực tế (MA)","definition":"the number of times the input force is multiplied","definitionVi":"Tỉ số giữa lực đầu ra và lực đầu vào: MA = F_out / F_in.","memoryTipVi":"Cho biết máy giúp giảm lực đi bao nhiêu lần."},{"term":"output work","termVi":"Công có ích / Công đầu ra (W_out)","definition":"output force multiplied by the distance over which it acts","definitionVi":"Công thực sự dùng để nâng vật hoặc hoàn thành nhiệm vụ.","memoryTipVi":"W_out luôn ≤ W_in."},{"term":"pulley","termVi":"Ròng rọc","definition":"a simple machine consisting of a rope that passes over one or more grooved wheels","definitionVi":"Bánh xe có rãnh vắt dây dùng để đổi hướng lực (ròng rọc cố định) hoặc giảm lực kéo (ròng rọc động).","memoryTipVi":"Ròng rọc động cho lợi 2 lần về lực."},{"term":"screw","termVi":"Đinh ốc / Vít","definition":"a simple machine consisting of a spiral inclined plane","definitionVi":"Mặt phẳng nghiêng quấn quanh một hình trụ.","memoryTipVi":"Bước ren càng nhỏ, lực siết càng lớn."},{"term":"simple machine","termVi":"Máy cơ đơn giản","definition":"a machine that makes work easier by changing the amount or direction of force required to move an object","definitionVi":"Thiết bị thay đổi độ lớn hoặc hướng của lực để thực hiện công dễ hơn (đòn bẩy, ròng rọc, mặt phẳng nghiêng...).","memoryTipVi":"Định luật về công: Được lợi bao nhiêu lần về lực thì thiệt bấy nhiêu lần về đường đi!"},{"term":"wedge","termVi":"Cái nêm (Lưỡi rìu, dao)","definition":"a simple machine consisting of two back-to-back inclined planes","definitionVi":"Hai mặt phẳng nghiêng ghép lưng vào nhau dùng để chẻ/tách vật.","memoryTipVi":"Ví dụ: lưỡi dao, mũi rìu."},{"term":"wheel and axle","termVi":"Bánh xe và trục","definition":"a simple machine consisting of a rod fixed to the center of a wheel","definitionVi":"Hai trụ đồng tâm khác bán kính quay cùng nhau (như vô lăng ô tô, tua-vít).","memoryTipVi":"IMA = R_bánh xe / r_trục."}],"assessments":[{"uid":"hsphys.ch09.sec03.q001","sourceId":"fs-id1167067296819","category":"check-understanding","categoryLabel":"Check Your Understanding (Kiểm tra đọc hiểu)","isMultipleChoice":true,"prompt":"True or falseThe efficiency of a simple machine is always less than 100 percent because some small fraction of the input work is always converted to heat energy due to friction.","images":[],"choices":[{"label":"a","text":"True"},{"label":"b","text":"False"}],"hasOfficialSolution":false,"solution":null},{"uid":"hsphys.ch09.sec03.q002","sourceId":"fs-id1167066847645","category":"check-understanding","categoryLabel":"Check Your Understanding (Kiểm tra đọc hiểu)","isMultipleChoice":false,"prompt":"The circular handle of a faucet is attached to a rod that opens and closes a valve when the handle is turned. If the rod has a diameter of 1 cm and the IMA of the machine is 6, what is the radius of the handle?\n0.08 cm\n0.17 cm\n3.0 cm\n6.0 cm","images":[],"choices":[],"hasOfficialSolution":false,"solution":null},{"uid":"hsphys.ch09.sec03.q004","sourceId":"fs-id1167067251931","category":"practice-problems","categoryLabel":"Practice Problems (Bài tập vận dụng)","isMultipleChoice":true,"prompt":"If a pulley system can lift a 200N load with an effort force of 52 N and has an efficiency of almost 100 percent, how many ropes are supporting the load?","images":[],"choices":[{"label":"a","text":"1 rope is required because the actual mechanical advantage is 0.26."},{"label":"b","text":"1 rope is required because the actual mechanical advantage is 3.80."},{"label":"c","text":"4 ropes are required because the actual mechanical advantage is 0.26."},{"label":"d","text":"4 ropes are required because the actual mechanical advantage is 3.80."}],"hasOfficialSolution":false,"solution":null},{"uid":"hsphys.ch09.sec03.q006","sourceId":"eip-id1166849847722","category":"concept","categoryLabel":"Concept Items (Câu hỏi khái niệm)","isMultipleChoice":true,"prompt":"Which type of simple machine is a knife?","images":[],"choices":[{"label":"a","text":"A ramp"},{"label":"b","text":"A wedge"},{"label":"c","text":"A pulley"},{"label":"d","text":"A screw"}],"hasOfficialSolution":false,"solution":null},{"uid":"hsphys.ch09.sec03.q010","sourceId":"fs-id1167067251931","category":"problems","categoryLabel":"Problems (Bài toán tính toán)","isMultipleChoice":true,"prompt":"If a pulley system can lift a 200N load with an effort force of 52 N and has an efficiency of almost 100 percent, how many ropes are supporting the load?","images":[],"choices":[{"label":"a","text":"1 rope is required because the actual mechanical advantage is 0.26."},{"label":"b","text":"1 rope is required because the actual mechanical advantage is 3.80."},{"label":"c","text":"4 ropes are required because the actual mechanical advantage is 0.26."},{"label":"d","text":"4 ropes are required because the actual mechanical advantage is 3.80."}],"hasOfficialSolution":false,"solution":null},{"uid":"hsphys.ch09.sec03.q011","sourceId":"fs-id1167067069696","category":"problems","categoryLabel":"Problems (Bài toán tính toán)","isMultipleChoice":true,"prompt":"A man is using a wedge to split a block of wood by hitting the wedge with a hammer. This drives the wedge into the wood creating a crack in the wood. When he hits the wedge with a force of 400 N it travels 4 cm into the wood. This caused the wedge to exert a force of 1,400 N sideways increasing the width of the crack by 1 cm . What is the efficiency of the wedge?","images":[],"choices":[{"label":"a","text":"0.875 percent"},{"label":"b","text":"0.14"},{"label":"c","text":"0.751"},{"label":"d","text":"87.5 percent"}],"hasOfficialSolution":false,"solution":null},{"uid":"hsphys.ch09.sec03.q012","sourceId":"fs-id1167063798774","category":"problems","categoryLabel":"Problems (Bài toán tính toán)","isMultipleChoice":true,"prompt":"An electrician grips the handles of a wire cutter, like the one shown, 10 cm from the pivot and places a wire between the jaws 2 cm from the pivot. If the cutter blades are 2 cm wide and 0.3 cm thick, what is the overall IMA of this complex machine?","images":[{"sourceId":"fs-id1164564453495","filename":"CNX_HSPhysics_09_03_wirecutter.jpg","relativePath":"media/CNX_HSPhysics_09_03_wirecutter.jpg","alt":"The image is a picture of wire cutters with red handles. The pinchers are closed."}],"choices":[{"label":"a","text":"1.34"},{"label":"b","text":"1.53"},{"label":"c","text":"33.3"},{"label":"d","text":"33.5"}],"hasOfficialSolution":false,"solution":null},{"uid":"hsphys.ch09.sec03.q013","sourceId":"fs-id1167066820750","category":"test-prep-mc","categoryLabel":"Test Prep — Trắc nghiệm","isMultipleChoice":true,"prompt":"A large radius divided by a small radius is the expression used to calculate the IMA of what?","images":[],"choices":[{"label":"a","text":"A screw"},{"label":"b","text":"A pulley"},{"label":"c","text":"A wheel and axle"},{"label":"d","text":"An inclined plane."}],"hasOfficialSolution":false,"solution":null},{"uid":"hsphys.ch09.sec03.q015","sourceId":"eip-id1166850157365","category":"test-prep-mc","categoryLabel":"Test Prep — Trắc nghiệm","isMultipleChoice":true,"prompt":"Which statement correctly describes the simple machines, like the crank in the image, that make up an Archimedes screw and the forces it applies?","images":[{"sourceId":"eip-idm276679808","filename":"CNX_Archimedes_screw.jpg","relativePath":"media/CNX_Archimedes_screw.jpg","alt":"A classic illustration of an Archimedes' screw, a historical water-lifting device, showing its helical design within a tube, used to transport water upwards from a lower to a higher level."}],"choices":[{"label":"a","text":"The crank is a wedge in which the IMA is the length of the tube divided by the radius of the tube. The applied force is the effort force and the\nweight of the water is the resistance force."},{"label":"b","text":"The crank is an inclined plane in which the IMA is the length of the tube divided by the radius of the tube. The applied force is the effort force and\nthe weight of the water is the resistance force."},{"label":"c","text":"The crank is a wheel and axle. The effort force of the crank becomes the resistance force of the screw."},{"label":"d","text":"The crank is a wheel and axle. The resistance force of the crank becomes the effort force of the screw."}],"hasOfficialSolution":false,"solution":null},{"uid":"hsphys.ch09.sec03.q016","sourceId":"eip-id1166849749527","category":"test-prep-mc","categoryLabel":"Test Prep — Trắc nghiệm","isMultipleChoice":true,"prompt":"Refer to the pulley system on right in the image. Assume this pulley system is an ideal machine.\nHow hard would you have to pull on the rope to lift a 120 N load?\nHow many meters of rope would you have to pull out of the system to lift the load 1 m?","images":[{"sourceId":"fs-id1164567622143","filename":"CNX_HSPhysics_09_03_pulleys.jpg","relativePath":"media/CNX_HSPhysics_09_03_pulleys.jpg","alt":"A series of 3 pulley systems are shown in this image. At the top of the image there is a formula I M A equals N. The first pulley on the left is shown. A red arrow is following diagonally down and to the right from the top of the pulley labeled F sub e. A weight is shown on the left side of the pulley with a red arrow from the weight denoted F sub r. A dotted line goes across the line from the weight to the pulley that reads N equals 1. The pulley in the center  has a red arrow on the right side of the pulley going directly up labeled F sub e. A dotted line goes between the pulley and the fixed portion labeled N equals 2. A weight is suspended straight down from the pulley. The pulley system on the right has four pulleys in vertical succession. The top pulley and bottom pulley are larger than the pulleys in the middle.  A red arrow is following diagonally down and to the right from the top of the pulley labeled F sub e. A dotted line goes between the two smaller pulleys in the middle labeled N equals 4. A hook on the bottom of the second pulley from the top starts a line that winds under the second smaller pulley, over the first smaller pulley, under the bottom larger pulley and over the top larger pulley. A weight is suspended from the bottom of the larger pulley."}],"choices":[{"label":"a","text":"480 N\n4 m"},{"label":"b","text":"480 N\n\\(\\frac{1}{4}\\)\nm"},{"label":"c","text":"30 N\n4 m"},{"label":"d","text":"30 N\n\\(\\frac{1}{4}\\) m"}],"hasOfficialSolution":false,"solution":null},{"uid":"hsphys.ch09.sec03.q017","sourceId":"fs-id1167066945029","category":"test-prep-sa","categoryLabel":"Test Prep — Trả lời ngắn","isMultipleChoice":true,"prompt":"Why would you expect the lever shown in the top image to have a greater efficiency than the inclined plane shown in the bottom image?","images":[{"sourceId":"eip-idm192465088","filename":"CNX_HSPhysics_09_03_levers.jpg","relativePath":"media/CNX_HSPhysics_09_03_levers.jpg","alt":"Two diagrams are shown side by side. The diagram on the left shows a drawing of a hand pulling a mail out of wood using a lever. The diagram on the right shows an illustration of a lever and a fulcrum. The fulcrum is closer to the left side of the lever than the right side. The distance of the left side of the lever is labeled L subscript r and the distance of the right side is labeled L subscript e. A force vector is pointing down on the left side and is labeled F subscript r, and a force vector is pointing down on the right side and is labeled F subscript e. The equation IMA equals L subscript e over L subscript r is also shown."},{"sourceId":"eip-idm217253744","filename":"CNX_HSPhysics_09_03_wedge.jpg","relativePath":"media/CNX_HSPhysics_09_03_wedge.jpg","alt":"Two diagrams are shown side-by-side. On the left, an inclined plane is shown. Its horizontal surface distance is labeled L and its height is labeled h. A box is shown on the surface with a force vector that points up the plane. The equation IMA equals L over h is shown. On the right, a wedge is shown. Its horizontal surface distance is labeled L. Its height is labeled t. The equation IMA equals L over t is also shown."}],"choices":[{"label":"a","text":"The resistance arm is shorter in case of the inclined plane."},{"label":"b","text":"The effort arm is shorter in case of the inclined plane."},{"label":"c","text":"The area of contact is greater in case of the inclined plane."}],"hasOfficialSolution":false,"solution":null},{"uid":"hsphys.ch09.sec03.q018","sourceId":"fs-id1167067184207","category":"test-prep-sa","categoryLabel":"Test Prep — Trả lời ngắn","isMultipleChoice":true,"prompt":"Why is the wheel on a wheelbarrow not a simple machine in the same sense as the simple machine in the image?","images":[{"sourceId":"eip-idm223568960","filename":"CNX_HSPhysics_09_03_wheel.jpg","relativePath":"media/CNX_HSPhysics_09_03_wheel.jpg","alt":"A diagram of a wheel is shown. The equation IMA equals capital R over lowercase r. A small grey circle is inside a larger blue circle. An arrow labeled lowercase r points from the center of the smaller circle to its edge. An arrow labeled capital R points from the center of the smaller circle to the edge of the larger circle. A mass is attached to the smaller circle and has a force vector, F subscript r, pointing downward from it. Another force vector, F subscript e, points downward and to the right from the edge of the larger circle."}],"choices":[{"label":"a","text":"The wheel on the wheelbarrow has no fulcrum."},{"label":"b","text":"The center of the axle is not the fulcrum for the wheels of a wheelbarrow."},{"label":"c","text":"The wheelbarrow differs in the way in which load is attached to the axle."},{"label":"d","text":"The wheelbarrow has less resistance force than a wheel and axle design."}],"hasOfficialSolution":false,"solution":null},{"uid":"hsphys.ch09.sec03.q019","sourceId":"fs-id1167067204652","category":"test-prep-sa","categoryLabel":"Test Prep — Trả lời ngắn","isMultipleChoice":true,"prompt":"A worker pulls down on one end of the rope of a pulley system with a force of 75 N to raise a hay bale tied to the other end of the rope. If she pulls the rope down 2.0 m and the bale raises 1.0 m, what else would you have to know to calculate the efficiency of the pulley system?","images":[],"choices":[{"label":"a","text":"the weight of the worker"},{"label":"b","text":"the weight of the hay bale"},{"label":"c","text":"the radius of the pulley"},{"label":"d","text":"the height of the pulley from ground"}],"hasOfficialSolution":false,"solution":null},{"uid":"hsphys.ch09.sec03.q020","sourceId":"fs-id1167067184144","category":"test-prep-sa","categoryLabel":"Test Prep — Trả lời ngắn","isMultipleChoice":true,"prompt":"True or falseA boy pushed a box with a weight of 300 N up a ramp. He said that, because the ramp was 1.0 m high and 3.0 m long, he must have been pushing with force of exactly 100 N.","images":[],"choices":[{"label":"a","text":"True"},{"label":"b","text":"False"}],"hasOfficialSolution":false,"solution":null},{"uid":"hsphys.ch09.sec03.q021","sourceId":"fs-id1167063582653","category":"test-prep-er","categoryLabel":"Test Prep — Tự luận mở rộng","isMultipleChoice":true,"prompt":"To dig a hole, one holds the handles together and thrusts the blades of a posthole digger, like the one in the image, into the ground. Next, the handles are pulled apart, which squeezes the dirt between them, making it possible to remove the dirt from the hole. This complex machine is composed of two pairs of two different simple machines. Identify and describe the parts that are simple machines and explain how you would find the IMA of each type of simple machine.","images":[{"sourceId":"fs-id1164567184711","filename":"CNX_HSPhysics_09_03_digger_img.jpg","relativePath":"media/CNX_HSPhysics_09_03_digger_img.jpg","alt":"A post hole digger is shown with yellow and black handles. The digging apparatus is to the right and the post hole digger is closed."}],"choices":[{"label":"a","text":"Each handle and its attached blade is a lever with the fulcrum at the hinge. Each blade is a wedge.\nThe IMA of a lever would be the length of the handle divided by the length of the blade. The IMA of the wedges would be the length of the blade divided by its width."},{"label":"b","text":"Each handle and its attached to blade is a lever with the fulcrum at the end. Each blade is a wedge.\nThe IMA of a lever would be the length of the handle divided by the length of the blade. The IMA of the wedges would be the length of the blade divided by its width."},{"label":"c","text":"Each handle and its attached blade is a lever with the fulcrum at the hinge. Each blade is a wedge.\nThe IMA of a lever would be the length of the handle multiplied by the length of the blade. The IMA of the wedges would be the length of the blade multiplied by its width."},{"label":"d","text":"Each handle and its attached blade is a lever with the fulcrum at the end. Each blade is a wedge.\nThe IMA of a lever would be the length of the handle multiplied by the length of the blade. The IMA of the wedges would be the length of the blade multiplied by its width."}],"hasOfficialSolution":false,"solution":null},{"uid":"hsphys.ch09.sec03.q022","sourceId":"fs-id1167067114879","category":"test-prep-er","categoryLabel":"Test Prep — Tự luận mở rộng","isMultipleChoice":false,"prompt":"A wooden crate is pulled up a ramp that is 1.0 m high and 6.0 m long. The crate is attached to a rope that is wound around an axle with a radius of 0.020 m . The axle is turned by a 0.20 m long handle. What is the overall IMA of the complex machine?\n6\n10\n16\n60","images":[],"choices":[],"hasOfficialSolution":false,"solution":null}],"stats":{"learningObjectiveCount":2,"keyEquationCount":10,"subsectionCount":3,"workedExampleCount":1,"snapLabCount":0,"glossaryCount":13,"assessmentCount":16}}],"summary":{"totalSections":4,"totalKeyEquations":17,"totalWorkedExamples":3,"totalSnapLabs":1,"totalGlossaryTerms":24,"totalAssessments":40,"referencedMediaCount":15},"qualityGate":{"passed":true,"checkedUids":55,"errors":[],"warnings":[]}};
